create or replace function public.security_sesion_vigente(p_usuario uuid,p_sesion uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where s.id=p_sesion and s.user_id=p_usuario and (s.not_after is null or s.not_after>now()) and u.deleted_at is null and (u.banned_until is null or u.banned_until<=now())) $$; revoke all on function public.security_sesion_vigente(uuid,uuid) from public,anon,authenticated; grant execute on function public.security_sesion_vigente(uuid,uuid) to service_role;
